Object.assign(SNIP,{"l32acc": "class TaiKhoan {\nprivate:                       // chỉ hàm thành viên (và friend) dùng được\n    string chu;\n    long long soDu;\npublic:                        // giao diện: ai cũng gọi được\n    TaiKhoan(string ten) : chu(ten), soDu(0) {}\n    bool rut(long long t) {    // mọi thay đổi số dư đều phải qua đây\n        if (t <= 0 || t > soDu) return false;\n        soDu -= t;\n        return true;\n    }\n    long long laySoDu() const { return soDu; }   // getter: chỉ đọc\n};\nTaiKhoan a(\"An\");\na.soDu = -500;    // LỖI biên dịch: 'soDu' is private within this context", "l32getset": "class SinhVien {\n    string ten;\n    double diem = 0;\npublic:\n    const string& layTen() const { return ten; }   // trả tham chiếu const: không chép, không sửa được\n    double layDiem() const { return diem; }\n    bool datDiem(double d) {                       // setter có kiểm tra\n        if (d < 0 || d > 10) return false;         // từ chối giá trị sai\n        diem = d;\n        return true;\n    }\n};"});PRESET_NOTES["l32"]={"Ví dụ: Dữ liệu công khai bị sửa sai": "Mọi thành viên của struct đều public nên chỗ nào cũng trừ tiền được, kể cả trừ quá số dư. Chương trình vẫn chạy và in ra số dư âm: lỗi logic không ai phát hiện. Ví dụ tiếp theo sửa bằng class với dữ liệu private.", "Ví dụ: Bảo vệ bằng private và hàm public": "soDu chỉ thay đổi qua nap và rut, và cả hai đều kiểm tra trước. Rút 5000 hay nạp số âm đều bị từ chối (trả về 0). Dù gọi các hàm public theo thứ tự nào, số dư cũng không bao giờ âm.", "Ví dụ: Hàm lấy và hàm đặt có kiểm tra": "datDiem từ chối điểm 11 nên diem vẫn là 0; lần sau đặt 8.5 thì được. layTen trả về const string&: không chép chuỗi, và người gọi không sửa được tên qua nó.", "Ví dụ: Đổi cách lưu bên trong": "Bên trong chỉ lưu một số: tổng số phút kể từ 0:00. Người dùng lớp không biết điều đó, họ chỉ gọi layGio, layPhut, cong. Muốn đổi sang lưu giờ và phút riêng thì chỉ sửa trong lớp; main giữ nguyên.", "Ví dụ: Hàm friend": "inSaoKe không phải hàm thành viên, nhưng được khai báo friend trong TaiKhoan nên đọc được chu, soDu. Bỏ dòng friend đi thì g++ báo lỗi truy cập private.", "Lỗi: truy cập thành viên private": "Thành viên của class mặc định là private, nên main không gán thẳng được: 'long long int TaiKhoan::soDu' is private within this context. Muốn thay đổi số dư, lớp phải cung cấp một hàm public có kiểm tra (ví dụ nap).", "Lỗi: hàm const sửa thành viên": "lay() hứa không sửa đối tượng (const) nhưng lại tăng giaTri: g++ báo increment of member 'BoDem::giaTri' in read-only object. Tách thành hai hàm: tang() để sửa, lay() const để đọc."};EX_HINTS["l32"]=[["Mọi kiểm tra nằm trong nap và rut; main chỉ gọi và in LOI khi hàm trả về false.", "Lệnh so không có số đi kèm: kiểm tra lệnh trước rồi mới đọc x."], ["tang trả về false khi gt đã bằng maxGT; giam trả về false khi gt đã bằng 0.", "Lệnh r (đặt lại) không bao giờ bị chặn."], ["Mảng số ngày của 12 tháng; tháng 2 có 29 ngày nếu năm nhuận.", "Chỉ gán d, m, y sau khi đã kiểm tra hợp lệ: đối tượng không bao giờ giữ một ngày sai."]];
