/* Bài 32 · Đóng gói
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const P32=[{label:"Ví dụ: Dữ liệu công khai bị sửa sai",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nstruct TaiKhoan {\n    string chu;\n    long long soDu;\n};\n\nint main() {\n    TaiKhoan a{\"An\", 1000};\n    a.soDu -= 5000;\n    cout << a.chu << \": \" << a.soDu << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Bảo vệ bằng private và hàm public",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass TaiKhoan {\n    string chu;\n    long long soDu;\npublic:\n    TaiKhoan(string ten, long long tien) : chu(ten), soDu(0) {\n        if (tien > 0) soDu = tien;\n    }\n    bool nap(long long t) {\n        if (t <= 0) return false;\n        soDu += t;\n        return true;\n    }\n    bool rut(long long t) {\n        if (t <= 0 || t > soDu) return false;\n        soDu -= t;\n        return true;\n    }\n    long long laySoDu() const {\n        return soDu;\n    }\n};\n\nint main() {\n    TaiKhoan a(\"An\", 1000);\n    cout << a.rut(5000) << \" \" << a.laySoDu() << \"\\n\";\n    cout << a.nap(-20) << \" \" << a.laySoDu() << \"\\n\";\n    cout << a.rut(300) << \" \" << a.laySoDu() << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Hàm lấy và hàm đặt có kiểm tra",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass SinhVien {\n    string ten;\n    double diem = 0;\npublic:\n    SinhVien(string t) : ten(t) {}\n    const string& layTen() const {\n        return ten;\n    }\n    double layDiem() const {\n        return diem;\n    }\n    bool datDiem(double d) {\n        if (d < 0 || d > 10) return false;\n        diem = d;\n        return true;\n    }\n};\n\nint main() {\n    SinhVien s(\"Binh\");\n    if (!s.datDiem(11)) cout << \"Diem 11 khong hop le\\n\";\n    s.datDiem(8.5);\n    cout << s.layTen() << \": \" << s.layDiem() << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Đổi cách lưu bên trong",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass ThoiGian {\n    int tongPhut;\npublic:\n    ThoiGian(int g, int p) : tongPhut((g * 60 + p) % 1440) {}\n    int layGio() const {\n        return tongPhut / 60;\n    }\n    int layPhut() const {\n        return tongPhut % 60;\n    }\n    void cong(int phut) {\n        tongPhut = (tongPhut + phut) % 1440;\n    }\n};\n\nint main() {\n    ThoiGian t(22, 45);\n    t.cong(90);\n    cout << t.layGio() << \" gio \" << t.layPhut() << \" phut\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Hàm friend",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass TaiKhoan {\n    string chu;\n    long long soDu;\npublic:\n    TaiKhoan(string ten, long long tien) : chu(ten), soDu(tien) {}\n    friend void inSaoKe(const TaiKhoan& t);\n};\n\nvoid inSaoKe(const TaiKhoan& t) {\n    cout << \"Chu: \" << t.chu << \"\\n\";\n    cout << \"So du: \" << t.soDu << \"\\n\";\n}\n\nint main() {\n    TaiKhoan a(\"Chi\", 2500);\n    inSaoKe(a);\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Lỗi: truy cập thành viên private",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass TaiKhoan {\n    long long soDu = 0;\npublic:\n    long long laySoDu() const {\n        return soDu;\n    }\n};\n\nint main() {\n    TaiKhoan a;\n    a.soDu = 1000000;\n    cout << a.laySoDu() << \"\\n\";\n    return 0;\n}"},{label:"Lỗi: hàm const sửa thành viên",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass BoDem {\n    int giaTri = 0;\npublic:\n    int lay() const {\n        giaTri++;\n        return giaTri;\n    }\n};\n\nint main() {\n    BoDem b;\n    cout << b.lay() << \"\\n\";\n    return 0;\n}"}];
const sim32=makeSim2(document.getElementById("sim-l32"),{id:"s32",presets:P32});
makeEx2(document.getElementById("ex-l32"),sim32,[{t:"Tài khoản ngân hàng",d:"Viết lớp <code>TaiKhoan<\/code> có số dư private (ban đầu 0), các hàm <code>bool nap(long long)<\/code>, <code>bool rut(long long)<\/code> (chỉ nhận số tiền dương, rút không quá số dư) và <code>long long laySoDu() const<\/code>. Nhập q (1 ≤ q ≤ 1000) rồi q lệnh: <code>nap x<\/code>, <code>rut x<\/code>, <code>so<\/code>. Với lệnh nap/rut bị từ chối in <code>LOI<\/code>; lệnh <code>so<\/code> in số dư.",tests:[{in:"5\nnap 100\nrut 30\nso\nrut 100\nso",out:"70\nLOI\n70"},{in:"3\nnap -5\nrut 0\nso",out:"LOI\nLOI\n0"},{in:"4\nnap 1000000000\nnap 1000000000\nnap 1000000000\nso",out:"3000000000"}],start:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass TaiKhoan {\n    long long soDu = 0;\npublic:\n    bool nap(long long t) {\n        // chỉ nhận t > 0\n        return false;\n    }\n    bool rut(long long t) {\n        // chỉ nhận 0 < t <= soDu\n        return false;\n    }\n    long long laySoDu() const {\n        return soDu;\n    }\n};\n\nint main() {\n    int q;\n    cin >> q;\n    TaiKhoan a;\n    for (int i = 0; i < q; i++) {\n        string lenh;\n        cin >> lenh;\n        // xử lý nap / rut / so\n    }\n    return 0;\n}",need:/class\s+TaiKhoan\s*\{\s*long\s+long\s+soDu[^;]*;\s*public\s*:/,needMsg:"Hãy giữ soDu là thành viên private (đứng trước public:) của class TaiKhoan."},{t:"Bộ đếm có giới hạn",d:"Viết lớp <code>BoDem<\/code> với hàm tạo <code>BoDem(int maxGT)<\/code>, giá trị ban đầu 0, các hàm <code>bool tang()<\/code>, <code>bool giam()<\/code> (không vượt khỏi đoạn [0, maxGT], trả về false nếu bị chặn), <code>void datLai()<\/code> và <code>int lay() const<\/code>. Nhập maxGT và một chuỗi lệnh gồm các ký tự <code>+<\/code>, <code>-<\/code>, <code>r<\/code>. In giá trị cuối và số lệnh bị chặn.",tests:[{in:"3\n++++-",out:"2 1"},{in:"0\n+-r",out:"0 2"},{in:"5\n+++r--+",out:"1 2"}],start:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass BoDem {\n    int gt, maxGT;\npublic:\n    BoDem(int m) : gt(0), maxGT(m) {}\n    // viết tang(), giam(), datLai(), lay()\n};\n\nint main() {\n    int m;\n    string lenh;\n    cin >> m >> lenh;\n    BoDem b(m);\n    int biChan = 0;\n    // duyệt từng ký tự của lenh\n    cout << b.lay() << \" \" << biChan << \"\\n\";\n    return 0;\n}",need:/class\s+BoDem[\s\S]*bool\s+tang\s*\(\s*\)[\s\S]*bool\s+giam\s*\(\s*\)[\s\S]*int\s+lay\s*\(\s*\)\s*const/,needMsg:"Hãy viết các hàm bool tang(), bool giam() và int lay() const trong lớp BoDem."},{t:"Ngày hợp lệ",d:"Viết lớp <code>Ngay<\/code> có ngày, tháng, năm private, hàm <code>bool dat(int d, int m, int y)<\/code> chỉ nhận ngày hợp lệ (tính cả năm nhuận: chia hết cho 400, hoặc chia hết cho 4 mà không chia hết cho 100; 1 ≤ y ≤ 9999) và hàm <code>void in() const<\/code> in DD/MM/YYYY. Nhập n rồi n bộ d m y; với mỗi bộ in ngày đã chuẩn định dạng hoặc <code>INVALID<\/code>.",tests:[{in:"4\n29 2 2024\n29 2 2023\n31 4 2020\n1 1 1",out:"29/02/2024\nINVALID\nINVALID\n01/01/0001"},{in:"2\n29 2 1900\n29 2 2000",out:"INVALID\n29/02/2000"},{in:"1\n31 12 9999",out:"31/12/9999"}],start:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass Ngay {\n    int d = 1, m = 1, y = 2000;\n    // có thể thêm hàm private kiểm tra năm nhuận, số ngày của tháng\npublic:\n    bool dat(int nd, int nm, int ny) {\n        // chỉ gán khi hợp lệ\n        return false;\n    }\n    void in() const {\n        // in DD/MM/YYYY\n    }\n};\n\nint main() {\n    int n;\n    cin >> n;\n    for (int i = 0; i < n; i++) {\n        int d, m, y;\n        cin >> d >> m >> y;\n        Ngay x;\n        if (x.dat(d, m, y)) x.in();\n        else cout << \"INVALID\\n\";\n    }\n    return 0;\n}",need:/class\s+Ngay[\s\S]*bool\s+dat\s*\(\s*int\s+\w+\s*,\s*int\s+\w+\s*,\s*int\s+\w+\s*\)[\s\S]*void\s+in\s*\(\s*\)\s*const/,needMsg:"Hãy giữ lớp Ngay với bool dat(int, int, int) và void in() const."}]);

makeQuiz("quiz32","score32",[{"q": "Thành viên khai báo trong <code>class<\/code> mà không ghi public/private thì có quyền gì?", "o": ["public", "private", "protected", "Tùy trình biên dịch"], "a": 1, "e": "Class mặc định private, struct mặc định public."}, {"q": "Vi phạm quyền truy cập (dùng thành viên private từ main) bị phát hiện khi nào?", "o": ["Lúc biên dịch", "Lúc chạy, chương trình dừng", "Không bao giờ", "Chỉ khi bật -Wall"], "a": 0, "e": "Đó là lỗi biên dịch: chương trình không được tạo ra."}, {"q": "Lợi ích chính của việc giấu dữ liệu sau các hàm public là gì?", "o": ["Chương trình chạy nhanh hơn", "Tiết kiệm bộ nhớ", "Giữ được bất biến và đổi cách lưu bên trong mà không phải sửa mã bên ngoài", "Không cần viết hàm tạo"], "a": 2, "e": "Mọi thay đổi đi qua vài hàm có kiểm tra; bên trong lớp có thể thay đổi tự do."}, {"q": "Hàm <code>friend void f(const A&amp; a);<\/code> khai báo trong lớp A có đặc điểm gì?", "o": ["f là hàm thành viên của A", "f không phải hàm thành viên nhưng đọc được thành viên private của A", "f chỉ đọc được thành viên public", "f được gọi tự động khi tạo A"], "a": 1, "e": "friend cho một hàm bên ngoài quyền truy cập private của lớp."}]);

